from urllib.parse import parse_qs
import re

def parse_query(value):
    # Check for malformed percent escapes by looking for % followed by non-hex characters
    if re.search(r'%[^\w%]', value):
        raise ValueError("Invalid query string")

    # Use parse_qs with keep_blank_values=True to preserve empty values
    parsed = parse_qs(value, keep_blank_values=True)

    # Return the last value for each key (as per the test case)
    return {key: values[-1] for key, values in parsed.items()}

